using System;using System.Linq;using System.Diagnostics;using System.IO;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using Newtonsoft.Json.Linq;using SpatialWallpaper.Sdk.Hosting;
namespace SpatialWallpaper.Supervision.Preview {
 static class PreviewProgram {
  static void Write(string path,JObject value){string temporary=path+".tmp";byte[] bytes=Encoding.UTF8.GetBytes(value.ToString(Newtonsoft.Json.Formatting.None));if(bytes.Length>32768)throw new InvalidDataException("preview-status-size");using(var file=new FileStream(temporary,FileMode.Create,FileAccess.Write,FileShare.Read)){file.Write(bytes,0,bytes.Length);file.Flush(true);}if(File.Exists(path))File.Replace(temporary,path,null);else File.Move(temporary,path);}
  [STAThread]static int Main(string[] args){DeterministicLlmServer mock=null;PreviewHostLease lease=null;PreviewWindow window=null;PinnedProcessOwner editor=null,self=null;System.Windows.Forms.Timer timer=null;string statusPath=null,stopPath=null,error=null;JObject manifest=null;int code=0;bool requested=false;long statusSequence=0;Exception uiFailure=null;
   if(args.Length==2&&args[0]=="--content-surface")return ContentSurfaceProgram.Run(args[1]);
   if(args.Length==2&&args[0]=="--native-input-source")return NativeInputSourceProgram.Run(args[1]);
   Func<bool> stopRequested=()=>requested||File.Exists(stopPath)||editor!=null&&editor.HasExited;
   Action<string> publish=state=>{if(statusPath==null)return;var receipt=window?.LastReceipt;string message=error??uiFailure?.GetBaseException().Message??window?.LastError;if(message!=null&&message.Length>2048)message=message.Substring(0,2048);Write(statusPath,new JObject{{"format",1},{"sequence",checked(++statusSequence)},{"state",state},{"viewer_pid",self?.Id??Process.GetCurrentProcess().Id},{"viewer_creation_filetime",self?.CreationFileTime??0},{"host_pid",lease?.HostId??0},{"host_creation_filetime",lease?.HostCreationFileTime??0},{"runtime_stage",manifest?["stage"]},{"receipt",receipt},{"error",message},{"window_resources_released",window==null||window.RuntimeResourcesReleased},{"host_resources_released",lease==null||lease.ResourcesReleased},{"forced_host_termination",lease?.ForcedTermination??false},{"host_diagnostic_tail",lease?.DiagnosticTail??""}});};
   try{
    if(args.Length!=1)throw new ArgumentException("preview configuration path required");var config=RuntimeDistribution.Read(args[0],16384);RuntimeDistribution.Fields(config,new[]{"format","toolchain","package","workspace","library","attempts","width","height","display_width","display_height","owner","llm"}.Concat(config.ContainsKey("audio")?new[]{"audio"}:new string[0]).ToArray());if(RuntimeDistribution.Integer(config["format"])!=1)throw new InvalidDataException("preview-configuration-version");string root=Path.GetFullPath(RuntimeDistribution.Text(config["toolchain"])),package=Path.GetFullPath(RuntimeDistribution.Text(config["package"])),workspace=Path.GetFullPath(RuntimeDistribution.Text(config["workspace"])),library=Path.GetFullPath(RuntimeDistribution.Text(config["library"])),attempts=Path.GetFullPath(RuntimeDistribution.Text(config["attempts"]));int width=RuntimeDistribution.Integer(config["width"]),height=RuntimeDistribution.Integer(config["height"]);float physicalWidth=RuntimeDistribution.Number(config["display_width"]),physicalHeight=RuntimeDistribution.Number(config["display_height"]);new ProjectionConfiguration(1,width,height,physicalWidth,physicalHeight,0,0,-.6f);RuntimeLimits.RequireRenderSize(width,height);
    Directory.CreateDirectory(workspace);if(Directory.EnumerateFileSystemEntries(workspace).Any(path=>Path.GetFileName(path)!="stop-request"))throw new InvalidDataException("preview-launch-workspace-not-fresh");if((File.GetAttributes(workspace)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("preview-workspace-link");statusPath=Path.Combine(workspace,"status.json");stopPath=Path.Combine(workspace,"stop-request");self=PinnedProcessOwner.PinCurrent();if(config["owner"].Type!=Newtonsoft.Json.Linq.JTokenType.Null){var owner=config["owner"] as JObject;RuntimeDistribution.Fields(owner,"pid","creation_filetime");if(owner["creation_filetime"].Type!=JTokenType.Integer)throw new InvalidDataException("preview-editor-owner");editor=PinnedProcessOwner.Open(RuntimeDistribution.Integer(owner["pid"]),(long)owner["creation_filetime"]);}publish("CheckingRuntime");using(var validation=new CancellationTokenSource()){var verifying=Task.Run(()=>RuntimeDistribution.Verify(root,validation.Token));while(!verifying.IsCompleted){if(stopRequested()){requested=true;validation.Cancel();}Thread.Sleep(25);}manifest=verifying.GetAwaiter().GetResult();}if(stopRequested())throw new OperationCanceledException("preview-owner-ended");
    var backend=new JObject{{"image",Path.Combine(root,"worker/player")},{"inventory",Path.Combine(root,"worker/report.json")},{"validator",Path.Combine(root,"validator")},{"state",Path.Combine(library,"backend")},{"attempts",attempts},{"width",width},{"height",height}};if(config["llm"].Type==JTokenType.Null){mock=new DeterministicLlmServer();backend["llm"]=mock.Configuration;}else backend["llm"]=config["llm"].DeepClone();if(config.ContainsKey("audio"))backend["audio"]=TrustedAudioSource.Validate(config["audio"]);lease=new PreviewHostLease(Path.Combine(root,"supervisor/Supervisor.exe"),Path.Combine(workspace,"host-config.json"),backend);publish("StartingHost");var starting=lease.StartAsync();while(!starting.IsCompleted){if(stopRequested()){requested=true;_ = lease.StopAsync();}Thread.Sleep(25);}starting.GetAwaiter().GetResult();if(stopRequested())throw new OperationCanceledException("preview-owner-ended");
    Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);ThreadExceptionEventHandler failure=(sender,eventArgs)=>{uiFailure=eventArgs.Exception;if(window!=null&&!window.IsDisposed)window.Close();else Application.ExitThread();};Application.ThreadException+=failure;
    try{window=new PreviewWindow(lease.Connection,package,library,width,height,physicalWidth,physicalHeight);window.ServiceStatus=mock!=null?"LLM：确定性本机模拟；外部服务未验证":"LLM：外部配置（未验证）";window.Text+=mock!=null?" · LLM 模拟":" · 外部 LLM 未验证";if((string)manifest["stage"]=="development")window.Text+=" · 开发版";window.Shown+=(sender,eventArgs)=>((Button)window.Controls.Find("StartPreview",true)[0]).PerformClick();bool sentClose=false;timer=new System.Windows.Forms.Timer{Interval=100};timer.Tick+=(sender,eventArgs)=>{try{if(stopRequested()&&!sentClose){sentClose=true;window.Close();}publish(window.IsDisposed?"Closing":window.State);}catch(Exception fault){uiFailure=fault;if(!sentClose){sentClose=true;window.Close();}}};timer.Start();Application.Run(window);if(window.LastError!=null||uiFailure!=null){error=uiFailure?.GetBaseException().Message??window.LastError;code=1;}}
    finally{timer?.Stop();timer?.Dispose();timer=null;Application.ThreadException-=failure;}
   }catch(OperationCanceledException)when(stopRequested()){requested=true;}catch(Exception fault){error=fault.GetBaseException().Message;Console.Error.WriteLine("Preview failed: "+error);code=1;}
   finally{
    try{if(window!=null&&!window.IsDisposed){if(!window.RuntimeResourcesReleased)throw new InvalidOperationException("preview-window-cleanup-unproven");window.Dispose();}}catch(Exception cleanup){error="preview-window-cleanup:"+cleanup.GetBaseException().Message;code=1;}
    try{if(lease!=null){lease.StopAsync().GetAwaiter().GetResult();lease.Dispose();}}catch(Exception cleanup){error="preview-host-cleanup:"+cleanup.GetBaseException().Message;code=1;}
    try{mock?.Dispose();}catch(Exception cleanup){error="preview-llm-mock-cleanup:"+cleanup.GetBaseException().Message;code=1;}
    try{publish(code==0?"Stopped":"Failed");}catch(Exception output){Console.Error.WriteLine("Preview status failed: "+output.GetBaseException().Message);code=1;}editor?.Dispose();self?.Dispose();
   }return code;
  }
 }
}
